    out = [row[:] for row in grid]
    points = {v: [(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x == v] for v in (1,2)}
    if len(points[1]) != 1 or len(points[2]) != 1:
        return out
    (r1,c1), = points[1]
    (r2,c2), = points[2]
    # The 3-path traces an L: first along the 2 marker's column to the 1 marker's row,
    # then along diagonals toward the 1 marker.
    dr = 1 if r1 > r2 else -1
    dc = 1 if c1 > c2 else -1
    r,c = r2,c2
    while r != r1:
        r += dr
        if grid[r][c] == 0:
            out[r][c] = 3
    while c != c1:
        r -= dr
        c -= dc
        if grid[r][c] == 0:
            out[r][c] = 3
    return out
