 "content": "def transform(grid):
    out = [row[:] for row in grid]
    one = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 1]
    two = [(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 2]
    if len(one) != 1 or len(two) != 1:
        return out
    (r1,c1), = one
    (r2,c2), = two
    dr = 1 if r2 > r1 else -1
    dc = 1 if c2 > c1 else -1
    r,c = r1,c1
    # Each marker emits a 3-colored path: travel diagonally toward the other
    # marker and turn to a straight ray along the direction of the larger gap.
    n = min(abs(r2-r1), abs(c2-c1))
    for _ in range(n):
        r += dr; c += dc
        if grid[r][c] == 0: out[r][c] = 3
    if abs(r2-r1) > abs(c2-c1):
        while r != r2:
            r += dr
            if grid[r][c] == 0: out[r][c] = 3
    else:
        while c != c2:
            c += dc
            if grid[r][c] == 0: out[r][c] = 3
    # The other half is a reflected path from marker 2 toward marker 1.
    r,c = r2,c2
    for _ in range(n):
        r -= dr; c -= dc
        if grid[r][c] == 0: out[r][c] = 3
    if abs(r2-r1) > abs(c2-c1):
        while r != r1:
            r -= dr
            if grid[r][c] == 0: out[r][c] = 3
    else:
        while c != c1:
            c -= dc
            if grid[r][c] == 0: out[r][c] = 3
    return out
